// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender) public {
        vm.assume(sender != address(0));
        vm.startPrank(sender);
        c.airDrop();
        uint256 balanceAfterFirst = c.tokenBalance(sender);
        vm.stopPrank();

        bool ok = false;
        vm.startPrank(sender);
        try c.airDrop() { ok = true; } catch { ok = false; }
        if (ok) {
            uint256 balanceAfterSecond = c.tokenBalance(sender);
            // The reference adds 20 again, totaling 40. The buggy one must never reach this because it reverts.
            assertTrue(balanceAfterSecond - balanceAfterFirst == 20);
        } else {
            // The buggy version reverts on the second call. Reference never reverts.
            assertTrue(false);
        }
        vm.stopPrank();
    }
}

